INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(494829, 48628, 10848, '<td valign="top">Very clever, this is a good shot a little grainy but other wise very well done I like it</td>', 'Very clever, this is a good shot a little grainy but other wise very well done I like it', '2003-11-26 00:08:38.000000', NULL, 1),
(494830, 48371, 327, '<td valign="top">Challenge: Scents and Aromas <br/>I''m sorry I don''t get the relationship. I used to raise ducks they really don''t have a stand out smell! lol I''m missing something here................sorry.</td>', 'Challenge: Scents and Aromas I''m sorry I don''t get the relationship. I used to raise ducks they really don''t have a stand out smell! lol I''m missing something here................sorry.', '2003-11-26 00:09:07.000000', NULL, 1),
(494831, 48593, 327, '<td valign="top">Real nice composition. Love the focus and lighting. Nicely done.</td>', 'Real nice composition. Love the focus and lighting. Nicely done.', '2003-11-26 00:10:10.000000', NULL, 1),
(494833, 48658, 327, '<td valign="top">I think the composition is pretty good here. The colors are. I would only suggest a correction on the lighting at the bottom on the ashtray. It could of been improved.</td>', 'I think the composition is pretty good here. The colors are. I would only suggest a correction on the lighting at the bottom on the ashtray. It could of been improved.', '2003-11-26 00:11:41.000000', NULL, 1),
(494836, 48380, 6597, '<td valign="top">good arrangement  like your colors 7</td>', 'good arrangement  like your colors 7', '2003-11-26 00:12:38.000000', NULL, 1),
(494838, 47854, 327, '<td valign="top">Wonderful smell, especially this time of year. Your flash need a bit of toning down. Give a plastic bag, napkin, or  tissue a try.......they will damper the bright light.</td>', 'Wonderful smell, especially this time of year. Your flash need a bit of toning down. Give a plastic bag, napkin, or  tissue a try.......they will damper the bright light.', '2003-11-26 00:13:23.000000', NULL, 1),
(494839, 48437, 327, '<td valign="top">Wonderful stand of trees. Really pretty with the shadows and sunlight. Your shot is blurry. Was this hand held? Could also be the sizing or compression. Still I do like this concept.</td>', 'Wonderful stand of trees. Really pretty with the shadows and sunlight. Your shot is blurry. Was this hand held? Could also be the sizing or compression. Still I do like this concept.', '2003-11-26 00:14:51.000000', NULL, 1),
(494842, 47982, 327, '<td valign="top">Super. Love the lighting here and the clean focus on the bottle. Nice going. I hope you do well in the challenge.</td>', 'Super. Love the lighting here and the clean focus on the bottle. Nice going. I hope you do well in the challenge.', '2003-11-26 00:15:50.000000', NULL, 1),
(494844, 47752, 10848, '<td valign="top">Beautiful shot, very vibrant colors,</td>', 'Beautiful shot, very vibrant colors,', '2003-11-26 00:17:46.000000', NULL, 1),
(494845, 48598, 327, '<td valign="top">Very pretty. I do think you could of left the cones out of the shot. They don''t seem to add much. The pot is good with the smoke but maybe the focus could of been more on the pot? I think this should do well, it''s an appealing shot.</td>', 'Very pretty. I do think you could of left the cones out of the shot. They don''t seem to add much. The pot is good with the smoke but maybe the focus could of been more on the pot? I think this should do well, it''s an appealing shot.', '2003-11-26 00:18:00.000000', NULL, 1),
(494847, 48550, 6008, '<td valign="top">Now that''s some steaming hot coffee. I really like the swirl of the one smoke curl near the top, it''s kinda cute. Not a fan of the composition, tho. Why did you decide to crop the bottom of the glass or the coffee pot? The smoke is good, the background is good, the glass is sharp and clear with not too many light reflections, it''s just the crop that doesnt do much for it.</td>', 'Now that''s some steaming hot coffee. I really like the swirl of the one smoke curl near the top, it''s kinda cute. Not a fan of the composition, tho. Why did you decide to crop the bottom of the glass or the coffee pot? The smoke is good, the background is good, the glass is sharp and clear with not too many light reflections, it''s just the crop that doesnt do much for it.', '2003-11-26 00:19:37.000000', NULL, 1),
(494848, 48248, 10848, '<td valign="top">Now this is gorgeous, the lighting is wonderful, the set up is beautiful good job on this one</td>', 'Now this is gorgeous, the lighting is wonderful, the set up is beautiful good job on this one', '2003-11-26 00:19:44.000000', NULL, 1),
(494852, 48466, 11184, '<td valign="top">Nice shot. Like the mug, really like the background, the lack of clutter and distractions, and the lighting, but may have had more impact if you actually showed the java by angling the shot down from a little higher up.  Then adding some steam would have really topped it off and made it less static....otherwise the sense of aroma has to be just further implied.</td>', 'Nice shot. Like the mug, really like the background, the lack of clutter and distractions, and the lighting, but may have had more impact if you actually showed the java by angling the shot down from a little higher up.  Then adding some steam would have really topped it off and made it less static....otherwise the sense of aroma has to be just further implied.', '2003-11-26 00:21:12.000000', NULL, 1),
(494853, 48440, 4969, '<td valign="top">I can smell it now!</td>', 'I can smell it now!', '2003-11-26 00:21:16.000000', NULL, 1),
(494854, 48529, 10848, '<td valign="top">This is a good shot, the lighting is good I like the angle leaving off the top but the top is visble in the mirror, good job</td>', 'This is a good shot, the lighting is good I like the angle leaving off the top but the top is visble in the mirror, good job', '2003-11-26 00:21:37.000000', NULL, 1),
(494855, 48362, 6008, '<td valign="top">First thing I notice is that the image is far too small. You have 640 pixels on the longest side and often it''s best to use them. Something so small makes it more difficult to see the image. If you''re not sure how to resize the image down to 640 using your editing software you could always post on the forum and I''m sure someone could help you out. The image itself is ok for what I can see, but it doesnt really do much else.</td>', 'First thing I notice is that the image is far too small. You have 640 pixels on the longest side and often it''s best to use them. Something so small makes it more difficult to see the image. If you''re not sure how to resize the image down to 640 using your editing software you could always post on the forum and I''m sure someone could help you out. The image itself is ok for what I can see, but it doesnt really do much else.', '2003-11-26 00:22:20.000000', NULL, 1),
(494857, 48639, 4969, '<td valign="top">Love the tones and the expression well done!</td>', 'Love the tones and the expression well done!', '2003-11-26 00:22:52.000000', NULL, 1),
(494858, 48444, 327, '<td valign="top">My junior high French is very poor...but I did look up to see what this was...Paper d?Arménie is oldest cleansing natural and deodorizer to l?air ambient. It purifies and scents to l?air houses, it removes the bad smells: tobacco, cracklings? You will like its delicate odor and its great capacity to purify to l?air will satisfy you.<br/> <br/>Now I know. Very interesting. Not sure if we have something like this in the USA. Hum, see I learned something, and to top it all off I enjoyed your photo. Very nice, good luck in the challenge.</td>', 'My junior high French is very poor...but I did look up to see what this was...Paper d?Arménie is oldest cleansing natural and deodorizer to l?air ambient. It purifies and scents to l?air houses, it removes the bad smells: tobacco, cracklings? You will like its delicate odor and its great capacity to purify to l?air will satisfy you. Now I know. Very interesting. Not sure if we have something like this in the USA. Hum, see I learned something, and to top it all off I enjoyed your photo. Very nice, good luck in the challenge.', '2003-11-26 00:23:07.000000', NULL, 1),
(494859, 48528, 11184, '<td valign="top">But those look like fairly clean and fragrant feet now.  Maybe should call it Ex-smelly feet.</td>', 'But those look like fairly clean and fragrant feet now.  Maybe should call it Ex-smelly feet.', '2003-11-26 00:23:15.000000', NULL, 1),
(494860, 48577, 10848, '<td valign="top">Very clever set up , the snow adds the "winterfresh" I like it</td>', 'Very clever set up , the snow adds the "winterfresh" I like it', '2003-11-26 00:23:46.000000', NULL, 1),
(494862, 48057, 10848, '<td valign="top">Nice shot, I like the shadowing on the petals.</td>', 'Nice shot, I like the shadowing on the petals.', '2003-11-26 00:24:38.000000', NULL, 1),
(494863, 48257, 4969, '<td valign="top">excellent ! My first thought was to put an open mouth in there somewhere?</td>', 'excellent ! My first thought was to put an open mouth in there somewhere?', '2003-11-26 00:24:41.000000', NULL, 1),
(494865, 48662, 327, '<td valign="top">Attractive light and color. The wrought iron rail is also a nice touch. I do smell fresh bread. :) Nice going good luck.</td>', 'Attractive light and color. The wrought iron rail is also a nice touch. I do smell fresh bread. :) Nice going good luck.', '2003-11-26 00:25:47.000000', NULL, 1),
(494866, 48153, 6008, '<td valign="top">I like that you''ve used the entire frame for the shot. The black background makes everything stand out nicely. The purple smoke is interesting and fairly well lit. The burner only has a very small section on the top where the light seems a little too bright but it''s not very distracting. I''m not sure about the border. At the bottom the golden color matches the burner, but around by the purple smoke it draws attention away from it a little.</td>', 'I like that you''ve used the entire frame for the shot. The black background makes everything stand out nicely. The purple smoke is interesting and fairly well lit. The burner only has a very small section on the top where the light seems a little too bright but it''s not very distracting. I''m not sure about the border. At the bottom the golden color matches the burner, but around by the purple smoke it draws attention away from it a little.', '2003-11-26 00:26:11.000000', NULL, 1),
(494867, 48585, 4969, '<td valign="top">WOW! Love the black and white and the mist and the cleavage! Bravo! Lighting excellent too! 9</td>', 'WOW! Love the black and white and the mist and the cleavage! Bravo! Lighting excellent too! 9', '2003-11-26 00:26:38.000000', NULL, 1),
(494869, 47926, 10848, '<td valign="top">This is good, the height add to this shot IMHO.</td>', 'This is good, the height add to this shot IMHO.', '2003-11-26 00:28:39.000000', NULL, 1),
(494870, 47765, 10848, '<td valign="top">This is cute,</td>', 'This is cute,', '2003-11-26 00:29:16.000000', NULL, 1),
(494874, 48642, 11184, '<td valign="top">I know that smell.  Bad smell, Good shot.  If you really wanted to get into it, I wonder how you could have further lit or tweaked the colors to emphasize the pungence and really make it clear that this is a smelly shot and not just a sports shot.  The socks alone really do a lot of the job though.  Good shot.</td>', 'I know that smell.  Bad smell, Good shot.  If you really wanted to get into it, I wonder how you could have further lit or tweaked the colors to emphasize the pungence and really make it clear that this is a smelly shot and not just a sports shot.  The socks alone really do a lot of the job though.  Good shot.', '2003-11-26 00:32:03.000000', NULL, 1),
(494876, 48668, 327, '<td valign="top">Just a super great idea. I love the composition along with the idea. Good color, focus and great humor!!!!!!!!!! Wonderful 9</td>', 'Just a super great idea. I love the composition along with the idea. Good color, focus and great humor!!!!!!!!!! Wonderful 9', '2003-11-26 00:32:23.000000', NULL, 1),
(494877, 48655, 10848, '<td valign="top">Great idea and very well executed, the crop on this is great, I like it</td>', 'Great idea and very well executed, the crop on this is great, I like it', '2003-11-26 00:32:33.000000', NULL, 1),
(494879, 48154, 6008, '<td valign="top">The cinamon sticks standing up like that just doesnt seem very natural to me. Having them more haphazard may have helped a little. I like the background, although not sure what it is. It adds to the earthy tone of the photograph. The colors are nice and rich and warm, and the border is complimentary. Having the bowl of spice in the center of the frame loses an impact, I think. Playing around with the placement of the sticks and the bowl could have made this good photograph even more dramatic.</td>', 'The cinamon sticks standing up like that just doesnt seem very natural to me. Having them more haphazard may have helped a little. I like the background, although not sure what it is. It adds to the earthy tone of the photograph. The colors are nice and rich and warm, and the border is complimentary. Having the bowl of spice in the center of the frame loses an impact, I think. Playing around with the placement of the sticks and the bowl could have made this good photograph even more dramatic.', '2003-11-26 00:35:17.000000', NULL, 1),
(494881, 48660, 10848, '<td valign="top">Very beautiful shot, the lighting is great on this, the colors are vivid and clear, good job</td>', 'Very beautiful shot, the lighting is great on this, the colors are vivid and clear, good job', '2003-11-26 00:35:59.000000', NULL, 1),
(494883, 48620, 11184, '<td valign="top">Nice shot.  I like the cleaness of the bright background and silver.  Only real improvement might be to go even further with that and work on bringing out even more of that lemony-fresh and clean feel through lighting and taking out some of the shadows and adding some sparkle for added punch.  Always easier said than done though, of course.  Good shot.</td>', 'Nice shot.  I like the cleaness of the bright background and silver.  Only real improvement might be to go even further with that and work on bringing out even more of that lemony-fresh and clean feel through lighting and taking out some of the shadows and adding some sparkle for added punch.  Always easier said than done though, of course.  Good shot.', '2003-11-26 00:37:45.000000', NULL, 1),
(494885, 48641, 10848, '<td valign="top">This is great! Very good capture, you caught the determined expression of the dog,.</td>', 'This is great! Very good capture, you caught the determined expression of the dog,.', '2003-11-26 00:38:01.000000', NULL, 1),
(494886, 48469, 6008, '<td valign="top">Hrm, looks like an amusement park ride. I think because of that any mountainous scent is a little lost. It''s an ok shot but doesnt quite fool the senses to imagine being in a mountain, just the memories of cotton candy and popcorn.</td>', 'Hrm, looks like an amusement park ride. I think because of that any mountainous scent is a little lost. It''s an ok shot but doesnt quite fool the senses to imagine being in a mountain, just the memories of cotton candy and popcorn.', '2003-11-26 00:38:01.000000', NULL, 1),
(494889, 48545, 11184, '<td valign="top">Ha, cute shot.  I like it and the idea of matching shirts was good.  And, of course, very good title.</td>', 'Ha, cute shot.  I like it and the idea of matching shirts was good.  And, of course, very good title.', '2003-11-26 00:39:55.000000', NULL, 1),
(494890, 47987, 6008, '<td valign="top">I could maybe see that you left the negative space above the cookies to allow for the presence of the smell to waft upwards, however, photogenically it doesnt really do much. There is a little too much space at the top and very little at the bottom. It''s good that you got in close to the subject but you needed to go all the way or else back up some. The lighting is good and the image is sharp, just needed some work on the composition, I think.</td>', 'I could maybe see that you left the negative space above the cookies to allow for the presence of the smell to waft upwards, however, photogenically it doesnt really do much. There is a little too much space at the top and very little at the bottom. It''s good that you got in close to the subject but you needed to go all the way or else back up some. The lighting is good and the image is sharp, just needed some work on the composition, I think.', '2003-11-26 00:42:05.000000', NULL, 1),
(494894, 48433, 11184, '<td valign="top">Cool.  Way to light that smoke...almost getting a little harsh on the lighting, but I like it.</td>', 'Cool.  Way to light that smoke...almost getting a little harsh on the lighting, but I like it.', '2003-11-26 00:43:05.000000', NULL, 1),
(494897, 47886, 12796, '<td valign="top">this is so good</td>', 'this is so good', '2003-11-26 00:44:51.000000', NULL, 1),
(494899, 48567, 11184, '<td valign="top">Ahh...I see that and immediately think of a rich aromatic blend.  Maybe a litttttle on the dark side, but that also somewhat adds to the ambiance.  Might have also been nice if the steam trailed up a little higher and more gradually, but now I''m being picky....because I like it though, of course.</td>', 'Ahh...I see that and immediately think of a rich aromatic blend.  Maybe a litttttle on the dark side, but that also somewhat adds to the ambiance.  Might have also been nice if the steam trailed up a little higher and more gradually, but now I''m being picky....because I like it though, of course.', '2003-11-26 00:46:22.000000', NULL, 1),
(494902, 47985, 6008, '<td valign="top">The idea is good, compositionally it''s good too. The downfall of this photo is the lighting. It seems a little dark and there is some noise on the white. I''m guessing this was partly to do with keeping down the amount of light reflections in the bottles. Most perfume shots are flooded with light and the backgrounds are very white. The dark corners/edges are where it is most noticeable. The only way I see to improve that is to use more lighting from more than one angle or perhaps trying to utilise natural light. This has the potential for being a good shot.</td>', 'The idea is good, compositionally it''s good too. The downfall of this photo is the lighting. It seems a little dark and there is some noise on the white. I''m guessing this was partly to do with keeping down the amount of light reflections in the bottles. Most perfume shots are flooded with light and the backgrounds are very white. The dark corners/edges are where it is most noticeable. The only way I see to improve that is to use more lighting from more than one angle or perhaps trying to utilise natural light. This has the potential for being a good shot.', '2003-11-26 00:47:09.000000', NULL, 1),
(494905, 48667, 11184, '<td valign="top">That mircrowave stuff really wreaks doesn''t it?  Don''t get me wrong I love me the convenience of some quick afternoon popcorn, but that smell of old feet really ruins it for me.</td>', 'That mircrowave stuff really wreaks doesn''t it?  Don''t get me wrong I love me the convenience of some quick afternoon popcorn, but that smell of old feet really ruins it for me.', '2003-11-26 00:48:39.000000', NULL, 1),
(494908, 48601, 13498, '<td valign="top">This photo is out of focus, but I like the idea</td>', 'This photo is out of focus, but I like the idea', '2003-11-26 00:51:50.000000', NULL, 1),
(494910, 48175, 6008, '<td valign="top">Is that plexiglass? It''s a cute idea and the composition is good. The white marks/reflections are a little distracting but not overly so. I''m not sure if it needs a tad more sharpness or contrast. The bright light from the top right makes the background a little uneven and forces some shadows that are a little noisy. An additional light in the bottom right may have helped a little.</td>', 'Is that plexiglass? It''s a cute idea and the composition is good. The white marks/reflections are a little distracting but not overly so. I''m not sure if it needs a tad more sharpness or contrast. The bright light from the top right makes the background a little uneven and forces some shadows that are a little noisy. An additional light in the bottom right may have helped a little.', '2003-11-26 00:52:30.000000', NULL, 1),
(494914, 47744, 9602, '<td valign="top">Ok, so the title explains it, but showing a mexican counting money next to Mary makes me think of church, not smells.</td>', 'Ok, so the title explains it, but showing a mexican counting money next to Mary makes me think of church, not smells.', '2003-11-26 00:54:12.000000', NULL, 1),
(494916, 48376, 9602, '<td valign="top">I like the idea, and the title helps explain it, but it would be nice for the photo to expain itself.</td>', 'I like the idea, and the title helps explain it, but it would be nice for the photo to expain itself.', '2003-11-26 00:55:04.000000', NULL, 1),
(494919, 48123, 13498, '<td valign="top">nasty</td>', 'nasty', '2003-11-26 00:56:21.000000', NULL, 1),
(494925, 48639, 12796, '<td valign="top">quite unique kind of photo... i really like this one</td>', 'quite unique kind of photo... i really like this one', '2003-11-26 01:01:53.000000', NULL, 1),
(494926, 48152, 6008, '<td valign="top">There seems to be a slight tilt to the jar or else it''s a perspective thing. I think this would have been much better in portrait mode where there would be more room to fill with the wonderful warm color and the smell/smoke. As it is now, it''s a little too centered with too much negative space on either side that doesnt add to the image.</td>', 'There seems to be a slight tilt to the jar or else it''s a perspective thing. I think this would have been much better in portrait mode where there would be more room to fill with the wonderful warm color and the smell/smoke. As it is now, it''s a little too centered with too much negative space on either side that doesnt add to the image.', '2003-11-26 01:02:52.000000', NULL, 1),
(494931, 48585, 11184, '<td valign="top">Ooo...magnifique.  Honest to god when the image first popped up it actually made me make this slow sexy inhaling expresion like I was some smooth French gigilo about to drop a steamy pick up line on some unsuspecting well dressed blonde woman wearing Chanel and shopping for handbags.  And I''ve never even been to France.  Mon dieu, now THAT''S good photography!!</td>', 'Ooo...magnifique.  Honest to god when the image first popped up it actually made me make this slow sexy inhaling expresion like I was some smooth French gigilo about to drop a steamy pick up line on some unsuspecting well dressed blonde woman wearing Chanel and shopping for handbags.  And I''ve never even been to France.  Mon dieu, now THAT''S good photography!!', '2003-11-26 01:09:11.000000', NULL, 1),
(494933, 48668, 9602, '<td valign="top">woulda been alittle better if you had an evergreen in the background, but still good.</td>', 'woulda been alittle better if you had an evergreen in the background, but still good.', '2003-11-26 01:10:22.000000', NULL, 1),
(494935, 48153, 9602, '<td valign="top">too much noise in the background.</td>', 'too much noise in the background.', '2003-11-26 01:11:17.000000', NULL, 1),
(494936, 48660, 11184, '<td valign="top">Beautifully done.  Happy holidays!</td>', 'Beautifully done.  Happy holidays!', '2003-11-26 01:12:40.000000', NULL, 1),
(494940, 48103, 7711, '<td valign="top">i would have liked it if you actually got closer to the bread so we could see  more of its texture and really feel like we''re getting at its beautiful aroma. This angle and lighting I just don''t find are doing the bread justice, though I appreciate the thought that went into the composition!</td>', 'i would have liked it if you actually got closer to the bread so we could see  more of its texture and really feel like we''re getting at its beautiful aroma. This angle and lighting I just don''t find are doing the bread justice, though I appreciate the thought that went into the composition!', '2003-11-26 01:14:43.000000', NULL, 1),
(494949, 48626, 13136, '<td valign="top">This is a great picture. The object top left is a bit distracting though.</td>', 'This is a great picture. The object top left is a bit distracting though.', '2003-11-26 01:23:02.000000', NULL, 1),
(494950, 47739, 7711, '<td valign="top">i really like the tones on this..can''t say I agree with the aroma in this picture..its not the first thing I think of when I see this, except that wild animals never smell very good! On composition, bw is always a good choice when it comes to a zebra ;) but I think that there is too much distracting stuff above his head...why did you leave it in? Do you think it adds to the message you are trying to convey? If you don''t have satisfactory answers to those questions, i think i''d consider cropping it out! :) nice capture though. :)</td>', 'i really like the tones on this..can''t say I agree with the aroma in this picture..its not the first thing I think of when I see this, except that wild animals never smell very good! On composition, bw is always a good choice when it comes to a zebra ;) but I think that there is too much distracting stuff above his head...why did you leave it in? Do you think it adds to the message you are trying to convey? If you don''t have satisfactory answers to those questions, i think i''d consider cropping it out! :) nice capture though. :)', '2003-11-26 01:23:58.000000', NULL, 1),
(494954, 48552, 11184, '<td valign="top">Oh that''s bad...haa...poor girl.  (I am of course referring to the one that has to sit closest to that smelly one up front)</td>', 'Oh that''s bad...haa...poor girl.  (I am of course referring to the one that has to sit closest to that smelly one up front)', '2003-11-26 01:25:53.000000', NULL, 1),
(494959, 48666, 1717, '<td valign="top">wow...i really love this!  the color is so vivid and the smoke is lit perfectly.  great work!!</td>', 'wow...i really love this!  the color is so vivid and the smoke is lit perfectly.  great work!!', '2003-11-26 01:29:37.000000', NULL, 1),
(494961, 48576, 11184, '<td valign="top">Great DOF and lighting.</td>', 'Great DOF and lighting.', '2003-11-26 01:30:47.000000', NULL, 1),
(494963, 48668, 11184, '<td valign="top">I like the texture and the oversatured background...really makes a photo like this work.</td>', 'I like the texture and the oversatured background...really makes a photo like this work.', '2003-11-26 01:33:42.000000', NULL, 1),
(494965, 48103, 11184, '<td valign="top">Thats a very nice bread shot...maybe a little steam to draw in and interact with and you''re set.</td>', 'Thats a very nice bread shot...maybe a little steam to draw in and interact with and you''re set.', '2003-11-26 01:35:20.000000', NULL, 1),
(494970, 48589, 12253, '<td valign="top">Nice clear shot.  Good comp too.</td>', 'Nice clear shot.  Good comp too.', '2003-11-26 01:40:26.000000', NULL, 1),
(494971, 48593, 11184, '<td valign="top">Nicccccce.  You are good.</td>', 'Nicccccce.  You are good.', '2003-11-26 01:40:31.000000', NULL, 1),
(494973, 48585, 1717, '<td valign="top">very nice lighting!</td>', 'very nice lighting!', '2003-11-26 01:41:20.000000', NULL, 1),
(494974, 47982, 11184, '<td valign="top">Great job.  Wonderful lighting and is that hair??  Fantastic.</td>', 'Great job.  Wonderful lighting and is that hair??  Fantastic.', '2003-11-26 01:41:57.000000', NULL, 1),
(494976, 48588, 12253, '<td valign="top">Lovely flower; it''s a nice, unusual composition, though the angle might be more dynamic I think.    You might watch your histogram for overexposure in the future, though I suspect this was a hard flower to photograph!  Harder still, it would be nice to have a bit more shadow detail on the leaf.</td>', 'Lovely flower; it''s a nice, unusual composition, though the angle might be more dynamic I think.    You might watch your histogram for overexposure in the future, though I suspect this was a hard flower to photograph!  Harder still, it would be nice to have a bit more shadow detail on the leaf.', '2003-11-26 01:43:04.000000', NULL, 1),
