(495544, 48273, 327, '<td valign="top">Humm, love garlic, the more the better. This is a nice macro. I think you did the lighting well also.</td>', 'Humm, love garlic, the more the better. This is a nice macro. I think you did the lighting well also.', '2003-11-26 11:45:16.000000', NULL, 1),
(495547, 48169, 11155, '<td valign="top">Holy smoke!  (haha)  Great capture.  Rose looks a little too artificial.  Smoke is great.  Title doesn''t really work for me.  Wonderful image overall, good luck.</td>', 'Holy smoke!  (haha)  Great capture.  Rose looks a little too artificial.  Smoke is great.  Title doesn''t really work for me.  Wonderful image overall, good luck.', '2003-11-26 11:46:04.000000', NULL, 1),
