(495918, 48550, 4008, '<td valign="top">I like how this image captures all the scents and aroma''s released when pouring the coffee. Very well done. Maybe a warm yellow/orange color instead of the blue would have given a better fit to the warmth of the coffee, but I must admit the blue is attractive as well. The purple glow of the coffee itself looks a bit strange, would have expected a bit more brown. Top 5 image for me.</td>', 'I like how this image captures all the scents and aroma''s released when pouring the coffee. Very well done. Maybe a warm yellow/orange color instead of the blue would have given a better fit to the warmth of the coffee, but I must admit the blue is attractive as well. The purple glow of the coffee itself looks a bit strange, would have expected a bit more brown. Top 5 image for me.', '2003-11-26 15:34:26.000000', NULL, 1),
(495919, 48553, 6942, '<td valign="top">nicely shot. The liting is amazing. I\''d like to see what kind of setup you used to get this. (10)<br/> <br/>-Tony-</td>', 'nicely shot. The liting is amazing. I\''d like to see what kind of setup you used to get this. (10) -Tony-', '2003-11-26 15:34:30.000000', NULL, 1),
(495920, 48214, 3032, '<td valign="top">Wonderful landscape, it indeed manages to communicate smell by making me remember what a cold winterday smells like. I think that there is nothing that smells better than nature on certain days, especially since it links to certain feelings of joy and other emotions.<br/>There are those days when you step outside, take a deep sniff of air and it smells just like it did 20 years ago, when I was just a little lad. You just know that it is going to be a wonderful day.</td>', 'Wonderful landscape, it indeed manages to communicate smell by making me remember what a cold winterday smells like. I think that there is nothing that smells better than nature on certain days, especially since it links to certain feelings of joy and other emotions.There are those days when you step outside, take a deep sniff of air and it smells just like it did 20 years ago, when I was just a little lad. You just know that it is going to be a wonderful day.', '2003-11-26 15:34:49.000000', NULL, 1),
(495921, 48460, 13025, '<td valign="top">Good, funny idea! ;) M.</td>', 'Good, funny idea! ;) M.', '2003-11-26 15:34:53.000000', NULL, 1),
(495923, 48536, 13136, '<td valign="top">May need a bit more light and better focus. Surprisingly one of only two flower pictures with someone sniffing. I like the composition.</td>', 'May need a bit more light and better focus. Surprisingly one of only two flower pictures with someone sniffing. I like the composition.', '2003-11-26 15:35:10.000000', NULL, 1),
(495924, 48593, 4008, '<td valign="top">Very strong, great soft and simple flow of smoke, with nice blue tints, pinsharp cigarette. Great composition following the flow of smoke. And capturing the essence of smell. A top image. 10 from me</td>', 'Very strong, great soft and simple flow of smoke, with nice blue tints, pinsharp cigarette. Great composition following the flow of smoke. And capturing the essence of smell. A top image. 10 from me', '2003-11-26 15:35:45.000000', NULL, 1),
(495925, 48153, 4008, '<td valign="top">An excellent capture of the scent itself. Good lighting. A top image. I don''t like the borderline running through the image itself.</td>', 'An excellent capture of the scent itself. Good lighting. A top image. I don''t like the borderline running through the image itself.', '2003-11-26 15:36:10.000000', NULL, 1),
(495926, 48480, 13136, '<td valign="top">Great catch on the spray. Good composition. The only real detraction is the dirty thumbnail.</td>', 'Great catch on the spray. Good composition. The only real detraction is the dirty thumbnail.', '2003-11-26 15:36:19.000000', NULL, 1),
(495927, 48065, 6942, '<td valign="top">Creative Idea. The DOF works well here.  (9)</td>', 'Creative Idea. The DOF works well here.  (9)', '2003-11-26 15:36:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(495928, 48206, 13025, '<td valign="top">Good framing and background.....M.</td>', 'Good framing and background.....M.', '2003-11-26 15:36:30.000000', NULL, 1),
(495929, 48593, 3032, '<td valign="top">Great detail on the cigaret tip, yet a silky smooth smoke with very nice tones= excellent aperture choice.<br/> <br/>Good photo.</td>', 'Great detail on the cigaret tip, yet a silky smooth smoke with very nice tones= excellent aperture choice. Good photo.', '2003-11-26 15:37:08.000000', NULL, 1),
(495930, 47967, 4008, '<td valign="top">The soft focus, the white shirt against white background, the rose nails, lips and bottle cap, all together adding to the expression of a soft feminine scent. very good.</td>', 'The soft focus, the white shirt against white background, the rose nails, lips and bottle cap, all together adding to the expression of a soft feminine scent. very good.', '2003-11-26 15:37:39.000000', NULL, 1),
(495931, 48598, 13025, '<td valign="top">Great exposure and composition.  M.</td>', 'Great exposure and composition.  M.', '2003-11-26 15:38:09.000000', NULL, 1),
(495932, 47927, 6942, '<td valign="top">Briliiant Photo. This looks like something you''d see in a shampoo or soap advertisement. Great job!<br/>(10)<br/>-Tony-</td>', 'Briliiant Photo. This looks like something you''d see in a shampoo or soap advertisement. Great job!(10)-Tony-', '2003-11-26 15:38:13.000000', NULL, 1),
(495936, 48020, 10625, '<td valign="top">i like the choice of border but not a whole lot of creativity here.  what type of soap?  i can''t relate a scent to it.</td>', 'i like the choice of border but not a whole lot of creativity here.  what type of soap?  i can''t relate a scent to it.', '2003-11-26 15:39:43.000000', NULL, 1),
(495938, 47936, 13136, '<td valign="top">Combining two scents was a good move. A little higher cropping and a little less light would have helped.</td>', 'Combining two scents was a good move. A little higher cropping and a little less light would have helped.', '2003-11-26 15:40:02.000000', NULL, 1),
(495939, 48533, 6942, '<td valign="top">Great shot. The colors kind of jump out at you. Nice job getting the bee in there. Another one that I could see in a shampoo/soap advertisement.  (10)<br/> <br/>-Tony-</td>', 'Great shot. The colors kind of jump out at you. Nice job getting the bee in there. Another one that I could see in a shampoo/soap advertisement.  (10) -Tony-', '2003-11-26 15:40:17.000000', NULL, 1),
(495942, 48065, 4008, '<td valign="top">Finally an animal picture which has a good fit to the challenge.</td>', 'Finally an animal picture which has a good fit to the challenge.', '2003-11-26 15:41:13.000000', NULL, 1),
(495943, 48206, 10625, '<td valign="top">a definitive smell!  good idea.  well focused.</td>', 'a definitive smell!  good idea.  well focused.', '2003-11-26 15:41:14.000000', NULL, 1),
(495945, 48591, 5534, '<td valign="top">One better photographs I''ve seen using smoke so far,  good job.</td>', 'One better photographs I''ve seen using smoke so far,  good job.', '2003-11-26 15:41:36.000000', NULL, 1),
(495946, 48635, 13136, '<td valign="top">One of the most irritating, yet still pleasant smells around. And the only one in the challenge to use pepper. I think it would work bettter with a whiter surface (more light?) to contrast the pepper better.</td>', 'One of the most irritating, yet still pleasant smells around. And the only one in the challenge to use pepper. I think it would work bettter with a whiter surface (more light?) to contrast the pepper better.', '2003-11-26 15:42:14.000000', NULL, 1),
(495947, 48585, 5534, '<td valign="top">Really like the use of light in this photo. Good job.</td>', 'Really like the use of light in this photo. Good job.', '2003-11-26 15:42:21.000000', NULL, 1),
(495948, 48169, 4008, '<td valign="top">Lovely composition and scene. Good capture of the smoke. Rose looks a bit overexposed.</td>', 'Lovely composition and scene. Good capture of the smoke. Rose looks a bit overexposed.', '2003-11-26 15:42:25.000000', NULL, 1),
(495949, 48593, 13025, '<td valign="top">Best of the smokes! Great exposure and composition. M;) M.</td>', 'Best of the smokes! Great exposure and composition. M;) M.', '2003-11-26 15:42:41.000000', NULL, 1),
(495951, 48273, 13025, '<td valign="top">Best of the garlic smelling ones..... M.</td>', 'Best of the garlic smelling ones..... M.', '2003-11-26 15:43:31.000000', NULL, 1),
(495952, 47927, 4008, '<td valign="top">Excellent rose picture, with great soft colors. Could do with a less dominating border.</td>', 'Excellent rose picture, with great soft colors. Could do with a less dominating border.', '2003-11-26 15:43:36.000000', NULL, 1),
(495954, 47777, 6942, '<td valign="top">Nice shot. Could probably use some brightness/contrast tweaking though. Other than that its nicely done.<br/>(8)<br/>-Tony-</td>', 'Nice shot. Could probably use some brightness/contrast tweaking though. Other than that its nicely done.(8)-Tony-', '2003-11-26 15:43:46.000000', NULL, 1),
(495956, 48575, 13025, '<td valign="top">Best of the roses. Great colour and freshness!  M.</td>', 'Best of the roses. Great colour and freshness!  M.', '2003-11-26 15:44:18.000000', NULL, 1),
(495957, 48440, 10625, '<td valign="top">not for me.  recreational. <br/>it looks as though it''s through a glass??, may have been sharper on a plain white background.</td>', 'not for me.  recreational. it looks as though it''s through a glass??, may have been sharper on a plain white background.', '2003-11-26 15:44:23.000000', NULL, 1),
(495958, 48154, 5534, '<td valign="top">Great photo. You really captured the textures of the spices well.</td>', 'Great photo. You really captured the textures of the spices well.', '2003-11-26 15:44:26.000000', NULL, 1),
(495960, 48448, 13136, '<td valign="top">Good contrast of subject colors and smells. Personally I have a hard time with the overbrightness of the right side, but still effective. Nice shot.</td>', 'Good contrast of subject colors and smells. Personally I have a hard time with the overbrightness of the right side, but still effective. Nice shot.', '2003-11-26 15:44:41.000000', NULL, 1),
(495964, 47987, 7628, '<td valign="top">Yummy, the chocolate does look warm and liquid.  I baked cookies too, and tried to photograph them for the challenge.  I kept trying to catch the steam that comes out when you break them open.  Too hard!  Yours look nice on the blue plate, but I don''t think the narrow DOF does anything for it - if you had a whole platter full the depth might add to the photo, but with just a few I think having them all sharp would be better.</td>', 'Yummy, the chocolate does look warm and liquid.  I baked cookies too, and tried to photograph them for the challenge.  I kept trying to catch the steam that comes out when you break them open.  Too hard!  Yours look nice on the blue plate, but I don''t think the narrow DOF does anything for it - if you had a whole platter full the depth might add to the photo, but with just a few I think having them all sharp would be better.', '2003-11-26 15:45:17.000000', NULL, 1),
(495965, 47912, 4008, '<td valign="top">You could use this for the soft focus challenge as well. Very good idea, an important smell in everyday life. I like the soft effect, keeps it a bit more distant from the actual person and emphasises more the experience/smell. Her expression is good as well, really taking in the smell.</td>', 'You could use this for the soft focus challenge as well. Very good idea, an important smell in everyday life. I like the soft effect, keeps it a bit more distant from the actual person and emphasises more the experience/smell. Her expression is good as well, really taking in the smell.', '2003-11-26 15:45:22.000000', NULL, 1),
(495969, 48030, 3032, '<td valign="top">Good portrait, nice lighting, like the angle at which you shot this person.<br/>I was thinking about the pose, there is some empty space to the left. On one hand that works good with the direction in which he looks. On the other hand I would like to see that bottom left filled up a bit more. I don''t know how one smokes a pipe, but perhaps a higher position of the end of the pipe and the hand supporting it from below (with the inside of the hand / fingers under the pipe) could help.<br/> <br/>Anyway, good job.</td>', 'Good portrait, nice lighting, like the angle at which you shot this person.I was thinking about the pose, there is some empty space to the left. On one hand that works good with the direction in which he looks. On the other hand I would like to see that bottom left filled up a bit more. I don''t know how one smokes a pipe, but perhaps a higher position of the end of the pipe and the hand supporting it from below (with the inside of the hand / fingers under the pipe) could help. Anyway, good job.', '2003-11-26 15:46:35.000000', NULL, 1),
(495973, 48617, 4008, '<td valign="top">Very harsh light, parts of the dog hardly recognisable., not even an eye visible. Does not express scent to me very well.</td>', 'Very harsh light, parts of the dog hardly recognisable., not even an eye visible. Does not express scent to me very well.', '2003-11-26 15:47:31.000000', NULL, 1),
(495975, 47982, 7628, '<td valign="top">intriguing effect on the upper left.  Works well as a scent, the gold color goes well with the name of the parfume.  The leaves at the bottom reflect the leaves on the bottle.  Perhaps it is a bit busy, my eye wanders not knowing what to focus on.  Maybe less leaves?</td>', 'intriguing effect on the upper left.  Works well as a scent, the gold color goes well with the name of the parfume.  The leaves at the bottom reflect the leaves on the bottle.  Perhaps it is a bit busy, my eye wanders not knowing what to focus on.  Maybe less leaves?', '2003-11-26 15:47:55.000000', NULL, 1),
(495977, 48311, 4008, '<td valign="top">Good capture but how does this fit into the challenge theme ?</td>', 'Good capture but how does this fit into the challenge theme ?', '2003-11-26 15:48:30.000000', NULL, 1),
(495978, 48257, 7628, '<td valign="top">very crisp and papery, maybe just a bit bright.  I like the random pattern the cloves make.</td>', 'very crisp and papery, maybe just a bit bright.  I like the random pattern the cloves make.', '2003-11-26 15:49:09.000000', NULL, 1),
(495982, 48585, 3032, '<td valign="top">This is add quality if you ask me. :)<br/>It is sexy, it is mystic, this must smell right! :)<br/>Love the lighting of this. Now I have to find some words for the composition, toning and such...... Very Good!</td>', 'This is add quality if you ask me. :)It is sexy, it is mystic, this must smell right! :)Love the lighting of this. Now I have to find some words for the composition, toning and such...... Very Good!', '2003-11-26 15:50:52.000000', NULL, 1),
(495983, 48440, 7628, '<td valign="top">I''m sure.  This is in a jar? odd red reflection. And the silver thing at the top is a bit of a distraction.  Maybe cropping in a concentrating on an interesting part of this picture would make a better composition.</td>', 'I''m sure.  This is in a jar? odd red reflection. And the silver thing at the top is a bit of a distraction.  Maybe cropping in a concentrating on an interesting part of this picture would make a better composition.', '2003-11-26 15:51:32.000000', NULL, 1),
(495989, 47744, 4008, '<td valign="top">What did the romans say ? Pecunia non olet, money does not stink. Is that why you photographed the money and not the mexican food ? Image could have been stronger by some more cropping, e.g. removing the bottle, concentrating more of the man counting his money.</td>', 'What did the romans say ? Pecunia non olet, money does not stink. Is that why you photographed the money and not the mexican food ? Image could have been stronger by some more cropping, e.g. removing the bottle, concentrating more of the man counting his money.', '2003-11-26 15:54:19.000000', NULL, 1),
(495990, 47982, 3032, '<td valign="top">Great composition with those leaves that come back in the bottle and the waves of scent. Wonderful colors and excellent job on the edgeless background.<br/> <br/>I wonder how you got the waves like that, it lookes like streaks of light in a multiple exposure or something like that. Or did you add it by hand during a long exposure? I should comment a lot more, this kind of wondering sparkles a lot of new ideas. :)</td>', 'Great composition with those leaves that come back in the bottle and the waves of scent. Wonderful colors and excellent job on the edgeless background. I wonder how you got the waves like that, it lookes like streaks of light in a multiple exposure or something like that. Or did you add it by hand during a long exposure? I should comment a lot more, this kind of wondering sparkles a lot of new ideas. :)', '2003-11-26 15:54:33.000000', NULL, 1),
(495993, 48565, 7628, '<td valign="top">Coriander?  Cinnamon, Anaise, and allspice... Doesn''t corriander look a bit like pepper?  Let me d=go check my kitchen shelf...anyway, I like all the warm rusty color, and the composition of different shapes.  The shinyness of the anaise seed compared to the roughness of the pod.  The shadows beneath detract a bit - wish they weren''t so obvios, or at least not so red.</td>', 'Coriander?  Cinnamon, Anaise, and allspice... Doesn''t corriander look a bit like pepper?  Let me d=go check my kitchen shelf...anyway, I like all the warm rusty color, and the composition of different shapes.  The shinyness of the anaise seed compared to the roughness of the pod.  The shadows beneath detract a bit - wish they weren''t so obvios, or at least not so red.', '2003-11-26 15:54:57.000000', NULL, 1),
(495994, 48451, 13136, '<td valign="top">This was a good idea to use smoke to represent odor. Unfortunatley there is too much smoke and the plate and silverware is almost invisible.</td>', 'This was a good idea to use smoke to represent odor. Unfortunatley there is too much smoke and the plate and silverware is almost invisible.', '2003-11-26 15:55:23.000000', NULL, 1),
(495996, 48562, 7628, '<td valign="top">Love it.  Garlic, I mean.  And I like the photo.  Your choice on a cutting block is a logical and hamonious background.  I think I would prefer a larger DOF - garlic has such nice papery texture and fine lines I''d like to see more. Nice light and color. 7</td>', 'Love it.  Garlic, I mean.  And I like the photo.  Your choice on a cutting block is a logical and hamonious background.  I think I would prefer a larger DOF - garlic has such nice papery texture and fine lines I''d like to see more. Nice light and color. 7', '2003-11-26 15:56:57.000000', NULL, 1),
(495997, 47818, 13136, '<td valign="top">Is this picture sideways or did you rotate it on purpose? Sorry, it''s just too unclear as to what the items in the picture are.</td>', 'Is this picture sideways or did you rotate it on purpose? Sorry, it''s just too unclear as to what the items in the picture are.', '2003-11-26 15:57:18.000000', NULL, 1),
(495998, 48020, 7628, '<td valign="top">I''d prefer to see the soap itself or some bubbly lather rather than the lable on the bottle.  You do get a nice color, and managed to minimize reflections.  The narrow DOF shows the curve of the bottle too.</td>', 'I''d prefer to see the soap itself or some bubbly lather rather than the lable on the bottle.  You do get a nice color, and managed to minimize reflections.  The narrow DOF shows the curve of the bottle too.', '2003-11-26 15:58:33.000000', NULL, 1),
(495999, 48466, 13136, '<td valign="top">Nice cup. But it needs some coffe in it or steam rising out, something to tell us it''s not a picture of a cup.</td>', 'Nice cup. But it needs some coffe in it or steam rising out, something to tell us it''s not a picture of a cup.', '2003-11-26 15:59:12.000000', NULL, 1),
(496002, 48591, 13136, '<td valign="top">It would have helped to have the cigar in the picture as well. At least the tip. Good capture of the smoke.</td>', 'It would have helped to have the cigar in the picture as well. At least the tip. Good capture of the smoke.', '2003-11-26 16:00:27.000000', NULL, 1),
(496003, 48371, 7628, '<td valign="top">Personally I don''t think ducks smell sweet.  The gray of the water makes a great backdrop to the colors of the duck, esp the green.  Doesn;t seem quite sharp tho''.</td>', 'Personally I don''t think ducks smell sweet.  The gray of the water makes a great backdrop to the colors of the duck, esp the green.  Doesn;t seem quite sharp tho''.', '2003-11-26 16:02:04.000000', NULL, 1),
(496004, 48575, 7628, '<td valign="top">wow.  nice detail.  The edges and the veins in the petals are great.  Maybe a bit much water.  Nice focus on the center of the bud, and the narrow DOF works to make us aware of the rest of the flower, but happy to soak up the deatil of a part of it.</td>', 'wow.  nice detail.  The edges and the veins in the petals are great.  Maybe a bit much water.  Nice focus on the center of the bud, and the narrow DOF works to make us aware of the rest of the flower, but happy to soak up the deatil of a part of it.', '2003-11-26 16:03:46.000000', NULL, 1),
(496005, 48200, 7628, '<td valign="top">unusual angle on a mug.  I like that beautiful tree on the left.  you drink your coffee in a great place.  Perhaps it is more than the smell of coffee, but also the smell of fesh air?  A nice combination - making us think not just of a particular scent but its place in our day.</td>', 'unusual angle on a mug.  I like that beautiful tree on the left.  you drink your coffee in a great place.  Perhaps it is more than the smell of coffee, but also the smell of fesh air?  A nice combination - making us think not just of a particular scent but its place in our day.', '2003-11-26 16:05:41.000000', NULL, 1),
(496009, 48617, 327, '<td valign="top">I think that your idea was good...for odors, smells. However the shot doesn''t work.<br/>It''s fired by the light. This is not high key, it''s over exposed.</td>', 'I think that your idea was good...for odors, smells. However the shot doesn''t work.It''s fired by the light. This is not high key, it''s over exposed.', '2003-11-26 16:07:06.000000', NULL, 1),
(496010, 48311, 327, '<td valign="top">Not sure how this is related to the challenge. Sorry don''t get it.</td>', 'Not sure how this is related to the challenge. Sorry don''t get it.', '2003-11-26 16:07:37.000000', NULL, 1),
(496011, 48093, 327, '<td valign="top">Where is your focus...not the dog we don''t see his face eyes/not the the bacon treat. I think this is a good idea, just not shot well. Cute weener dog, my husband loves them. Maybe if the light had been in front of the dog?</td>', 'Where is your focus...not the dog we don''t see his face eyes/not the the bacon treat. I think this is a good idea, just not shot well. Cute weener dog, my husband loves them. Maybe if the light had been in front of the dog?', '2003-11-26 16:09:01.000000', NULL, 1),
(496012, 48467, 7628, '<td valign="top">That gel makes for an intriguing light effect, especially against the black.  More visual than olfactory. Could be sharper on the gel part.  While the lable helps us to understand the subject, it needn''t be in focus, it might distract less if it were less sharp, but still give aid to meaning.</td>', 'That gel makes for an intriguing light effect, especially against the black.  More visual than olfactory. Could be sharper on the gel part.  While the lable helps us to understand the subject, it needn''t be in focus, it might distract less if it were less sharp, but still give aid to meaning.', '2003-11-26 16:09:11.000000', NULL, 1),
(496013, 48083, 327, '<td valign="top">Huh, I think that the camera moved on you. They do sometimes with hitting the button.</td>', 'Huh, I think that the camera moved on you. They do sometimes with hitting the button.', '2003-11-26 16:09:35.000000', NULL, 1),
(496014, 48461, 7628, '<td valign="top">Maybe the oil itself would carry the message better than the bottle.  This picture is so cool and detached, massage oil is warm and tactile - maybe a picture of oil on skin with warn lighting with the bottle slightly out of focus in the background?</td>', 'Maybe the oil itself would carry the message better than the bottle.  This picture is so cool and detached, massage oil is warm and tactile - maybe a picture of oil on skin with warn lighting with the bottle slightly out of focus in the background?', '2003-11-26 16:11:04.000000', NULL, 1),
(496017, 48448, 7628, '<td valign="top">Pretty pepper.  I like how you arranged it with stem looking down into the kife.  The chopped garlic and the knife tell a story about cooking and preparation for a yummy meal, makes me think of aroma!  the colors are fine, I think larger DOF, and a bit less bright..</td>', 'Pretty pepper.  I like how you arranged it with stem looking down into the kife.  The chopped garlic and the knife tell a story about cooking and preparation for a yummy meal, makes me think of aroma!  the colors are fine, I think larger DOF, and a bit less bright..', '2003-11-26 16:13:00.000000', NULL, 1),
(496019, 47744, 7628, '<td valign="top">Cute candid.  I like the smell of mexican food!  Wish the focus were a bit sharper on the man, but I like how he is in relation to his colorful surroundings.  His white shirt is a bit bright - details washed out.</td>', 'Cute candid.  I like the smell of mexican food!  Wish the focus were a bit sharper on the man, but I like how he is in relation to his colorful surroundings.  His white shirt is a bit bright - details washed out.', '2003-11-26 16:14:29.000000', NULL, 1),
(496021, 48440, 2223, '<td valign="top">Yeah right!</td>', 'Yeah right!', '2003-11-26 16:17:04.000000', NULL, 1),
(496022, 48529, 7628, '<td valign="top">Yes - my husband wears this.  Hot, well, he IS from ICEland.  But then again, Icelandic men are hot!  But I digress.  I like the play of warm colors inside the botlle.  The narrow DOF is ok, but the reflection doesn''t really add to the photo for me.  The background it cool, perhaps a warmer setting would help to imply the scent?</td>', 'Yes - my husband wears this.  Hot, well, he IS from ICEland.  But then again, Icelandic men are hot!  But I digress.  I like the play of warm colors inside the botlle.  The narrow DOF is ok, but the reflection doesn''t really add to the photo for me.  The background it cool, perhaps a warmer setting would help to imply the scent?', '2003-11-26 16:18:07.000000', NULL, 1),
(496023, 48546, 5792, '<td valign="top">Good lighting, good framing and nice capture of spray from the can.</td>', 'Good lighting, good framing and nice capture of spray from the can.', '2003-11-26 16:18:37.000000', NULL, 1),
(496024, 48459, 5792, '<td valign="top">Nice black background and good lighting. Fresh baked bread always has a nice aroma and you have captured it well here.</td>', 'Nice black background and good lighting. Fresh baked bread always has a nice aroma and you have captured it well here.', '2003-11-26 16:20:21.000000', NULL, 1),
(496025, 47873, 7628, '<td valign="top">Nice angle.  I like the hedge looming up into the sky, and that uneven fence lining the walk.  I''d frame it so the sign was front  and center - right now it is just a chenck of out of focus sidewalk.  Crop some on the bottom, and you''ll keep the nice lines of the sidewalk and the hedge with all the damp autums smells they imply, but gain a bit of focus (figuratively)</td>', 'Nice angle.  I like the hedge looming up into the sky, and that uneven fence lining the walk.  I''d frame it so the sign was front  and center - right now it is just a chenck of out of focus sidewalk.  Crop some on the bottom, and you''ll keep the nice lines of the sidewalk and the hedge with all the damp autums smells they imply, but gain a bit of focus (figuratively)', '2003-11-26 16:20:44.000000', NULL, 1),
(496027, 48214, 5792, '<td valign="top">Very beautiful shot. The reflection and misty morning are excellent.</td>', 'Very beautiful shot. The reflection and misty morning are excellent.', '2003-11-26 16:23:17.000000', NULL, 1),
(496029, 48575, 5792, '<td valign="top">Flowers are good subjects for photography, but this one is exceptionally well photographed.</td>', 'Flowers are good subjects for photography, but this one is exceptionally well photographed.', '2003-11-26 16:24:17.000000', NULL, 1),
(496031, 48550, 7628, '<td valign="top">These clouds od steam are wonderful!  The blue light is remisicent of morning, everthing is fresh including the coffee.  The glare on the glass is a bit distracting, I like the little flare of light on the pouring coffee.  a favorite. 9</td>', 'These clouds od steam are wonderful!  The blue light is remisicent of morning, everthing is fresh including the coffee.  The glare on the glass is a bit distracting, I like the little flare of light on the pouring coffee.  a favorite. 9', '2003-11-26 16:26:46.000000', NULL, 1),
(496033, 47967, 5792, '<td valign="top">Beautiful. Soft focus and delicate contrast work perfect for this image. Composition and framing are fine. The only negative is that the subjects hand extends to the edge of the frame.</td>', 'Beautiful. Soft focus and delicate contrast work perfect for this image. Composition and framing are fine. The only negative is that the subjects hand extends to the edge of the frame.', '2003-11-26 16:27:44.000000', NULL, 1),
(496034, 48553, 7628, '<td valign="top">Wish we couod see the source of the smoke.  The smoke itself is a great capture - neon blue!    Tis would look pretty cool and abstract cropped in from the right so all you have are th horizontal lines.  Almost a landscape of smoke?  Maybe too sparse tho''</td>', 'Wish we couod see the source of the smoke.  The smoke itself is a great capture - neon blue!    Tis would look pretty cool and abstract cropped in from the right so all you have are th horizontal lines.  Almost a landscape of smoke?  Maybe too sparse tho''', '2003-11-26 16:29:07.000000', NULL, 1),
