INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(496975, 48451, 11467, '<td valign="top">Background is a little dark. I can''t make out what is left or right foreground</td>', 'Background is a little dark. I can''t make out what is left or right foreground', '2003-11-27 15:44:21.000000', NULL, 1),
(496976, 48591, 10858, '<td valign="top">I hate cigar smoke, I LOVE the shot! :-) Wonderful composition, I like the smoke going on the diagonal from one corner to the other, and I like the shapes very much, that the smoke has. B&amp;W is excellent for this shot, it''s simple and great, my favourite kind of photo. Congrats, and good luck! :-)</td>', 'I hate cigar smoke, I LOVE the shot! :-) Wonderful composition, I like the smoke going on the diagonal from one corner to the other, and I like the shapes very much, that the smoke has. B&W is excellent for this shot, it''s simple and great, my favourite kind of photo. Congrats, and good luck! :-)', '2003-11-27 15:44:34.000000', NULL, 1),
(496978, 48009, 11467, '<td valign="top">Would be better if smoke was in the picture I think</td>', 'Would be better if smoke was in the picture I think', '2003-11-27 15:45:16.000000', NULL, 1),
(496979, 48256, 11467, '<td valign="top">Lighting is a little flat I think</td>', 'Lighting is a little flat I think', '2003-11-27 15:46:31.000000', NULL, 1),
(496980, 48566, 11467, '<td valign="top">Awww cute!!</td>', 'Awww cute!!', '2003-11-27 15:47:05.000000', NULL, 1),
(496981, 47926, 11467, '<td valign="top">A littl back lighting might have brought out the smoke more.</td>', 'A littl back lighting might have brought out the smoke more.', '2003-11-27 15:48:14.000000', NULL, 1),
(496983, 48273, 11467, '<td valign="top">I feel the garlic clove on the left distracts from the quality of the image.</td>', 'I feel the garlic clove on the left distracts from the quality of the image.', '2003-11-27 15:49:49.000000', NULL, 1),
(496984, 48536, 11467, '<td valign="top">A little dark &amp; flat lighting.</td>', 'A little dark & flat lighting.', '2003-11-27 15:50:51.000000', NULL, 1),
