(497602, 48569, 14253, '<td valign="top">I think it would be better either cropped below the scarf: or back up, raise the cup and show part of the face.</td>', 'I think it would be better either cropped below the scarf: or back up, raise the cup and show part of the face.', '2003-11-28 14:57:39.000000', NULL, 1),
(497604, 48662, 14253, '<td valign="top">I would probably appreciate it more if I had been there. On my monitor the three trees on the left are blown out.</td>', 'I would probably appreciate it more if I had been there. On my monitor the three trees on the left are blown out.', '2003-11-28 15:02:04.000000', NULL, 1),
