(497633, 48548, 7038, '<td valign="top">Interesting effect, but neither picture does much to hold my interest for long.  Possibly a better background would help.</td>', 'Interesting effect, but neither picture does much to hold my interest for long.  Possibly a better background would help.', '2003-11-28 15:28:52.000000', NULL, 1),
(497656, 48103, 3295, '<td valign="top">Yum... The lighting looks a little hot but I like that its direction, The background has weir blotches, would have like the color warmed even more.</td>', 'Yum... The lighting looks a little hot but I like that its direction, The background has weir blotches, would have like the color warmed even more.', '2003-11-28 15:58:40.000000', NULL, 1),
(497658, 48461, 3295, '<td valign="top">lacks pop.  I think maybe backlighting it a little, and having a reflector on the right would have helped- but not a very promising subject.</td>', 'lacks pop.  I think maybe backlighting it a little, and having a reflector on the right would have helped- but not a very promising subject.', '2003-11-28 15:59:38.000000', NULL, 1),
