(497662, 47926, 3295, '<td valign="top">missing something for me?  don''t know what it is but I feel no emotion. Nice shot though, nice lighting of the smoke.</td>', 'missing something for me?  don''t know what it is but I feel no emotion. Nice shot though, nice lighting of the smoke.', '2003-11-28 16:02:18.000000', NULL, 1),
(497665, 48552, 3295, '<td valign="top">cute.  Maybe could have viewed with arm filling the entire left of the pic with everyone behind slightly out of focus?</td>', 'cute.  Maybe could have viewed with arm filling the entire left of the pic with everyone behind slightly out of focus?', '2003-11-28 16:03:33.000000', NULL, 1),
(497666, 48380, 3295, '<td valign="top">The purple thing is ugly, everthing else is a little hot and over saturated for me, Try side lighting to add mood.</td>', 'The purple thing is ugly, everthing else is a little hot and over saturated for me, Try side lighting to add mood.', '2003-11-28 16:04:42.000000', NULL, 1),
(497667, 48569, 10260, '<td valign="top">This is so creatively put together!  Great photo, and greate idea for the challenge.  I like this because it''s something different.  Interesting concept in keeping the person out of the image and choosing just the props that tell the story of your title. 10</td>', 'This is so creatively put together!  Great photo, and greate idea for the challenge.  I like this because it''s something different.  Interesting concept in keeping the person out of the image and choosing just the props that tell the story of your title. 10', '2003-11-28 16:04:51.000000', NULL, 1),
(497669, 48663, 3295, '<td valign="top">beautiful (and I hate flower pics!) nice lighting and composition</td>', 'beautiful (and I hate flower pics!) nice lighting and composition', '2003-11-28 16:05:51.000000', NULL, 1),
(497671, 47873, 3295, '<td valign="top">you seem torn as to what your showing me.  Is the road sign or the bushes or the leaves?</td>', 'you seem torn as to what your showing me.  Is the road sign or the bushes or the leaves?', '2003-11-28 16:06:23.000000', NULL, 1),
