(497675, 48154, 3295, '<td valign="top">Fantastic backdrop.  I think even warmer colors and lower lighting could have helped.</td>', 'Fantastic backdrop.  I think even warmer colors and lower lighting could have helped.', '2003-11-28 16:08:16.000000', NULL, 1),
