(500176, 48256, 8530, '<td valign="top">Whoa. Now I feel dizzy.<br/> <br/>Interesting angle, and nice use of colour.</td>', 'Whoa. Now I feel dizzy. Interesting angle, and nice use of colour.', '2003-12-01 14:02:19.000000', NULL, 1),
(500181, 47927, 8530, '<td valign="top">Okay, I must admit that I''ve been of the feeling flower pictures in this challenge were a little too ''easy'' -- which is to say, not all that original. But this is just stunning. I even don''t mind the border; it gives it a very post-cardy feel, and I''m a big fan of commercial art when it''s done well, so that''s a plus. Also, I''m really impressed you managed to find what appears to be a completely perfect white rose. Very nice.</td>', 'Okay, I must admit that I''ve been of the feeling flower pictures in this challenge were a little too ''easy'' -- which is to say, not all that original. But this is just stunning. I even don''t mind the border; it gives it a very post-cardy feel, and I''m a big fan of commercial art when it''s done well, so that''s a plus. Also, I''m really impressed you managed to find what appears to be a completely perfect white rose. Very nice.', '2003-12-01 14:04:57.000000', NULL, 1),
(500182, 48214, 14671, '<td valign="top">serenity at last</td>', 'serenity at last', '2003-12-01 14:05:09.000000', NULL, 1),
