INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(501474, 48639, 12253, '<td valign="top">My favorite theme!  Composition is good; Lighting is a bit harsh though and three seems to be some reflection on the subject''s face on the right which is distracting.  Maybe it is steam, which is good, but it doesn''t look good over the eye here.</td>', 'My favorite theme!  Composition is good; Lighting is a bit harsh though and three seems to be some reflection on the subject''s face on the right which is distracting.  Maybe it is steam, which is good, but it doesn''t look good over the eye here.', '2003-12-02 20:50:28.000000', NULL, 1),
(501479, 48548, 11034, '<td valign="top">How do you did this shoot?</td>', 'How do you did this shoot?', '2003-12-02 20:59:05.000000', NULL, 1),
(501482, 48541, 3306, '<td valign="top">Nice capture but the smell of freedom?</td>', 'Nice capture but the smell of freedom?', '2003-12-02 21:01:48.000000', NULL, 1),
(501484, 48406, 3306, '<td valign="top">Nice set up but I think the reflection is distracting. I would have liked it much more on a non reflective surface</td>', 'Nice set up but I think the reflection is distracting. I would have liked it much more on a non reflective surface', '2003-12-02 21:02:53.000000', NULL, 1),
(501486, 48670, 3306, '<td valign="top">I like the idea but the shadow is a little distracting and the coffee bean is a little out of focus.</td>', 'I like the idea but the shadow is a little distracting and the coffee bean is a little out of focus.', '2003-12-02 21:04:29.000000', NULL, 1),
(501488, 48210, 3306, '<td valign="top">Nice idea. I like the color. The liquid below the oranges is distracting though.</td>', 'Nice idea. I like the color. The liquid below the oranges is distracting though.', '2003-12-02 21:05:46.000000', NULL, 1),
(501489, 47765, 3306, '<td valign="top">Smelly dog? Maybe she should have a bath!</td>', 'Smelly dog? Maybe she should have a bath!', '2003-12-02 21:06:20.000000', NULL, 1),
(501492, 47980, 3306, '<td valign="top">No Question this fits the challenge.</td>', 'No Question this fits the challenge.', '2003-12-02 21:06:47.000000', NULL, 1),
(501494, 48317, 3306, '<td valign="top">Smelly cat? I think he is drinking not smelling.</td>', 'Smelly cat? I think he is drinking not smelling.', '2003-12-02 21:07:29.000000', NULL, 1),
(501496, 48598, 3306, '<td valign="top">Very difficult picture. Nice job capturing the smoke.</td>', 'Very difficult picture. Nice job capturing the smoke.', '2003-12-02 21:08:29.000000', NULL, 1),
