(501499, 48663, 3306, '<td valign="top">Nice. Interesting lighting.</td>', 'Nice. Interesting lighting.', '2003-12-02 21:09:54.000000', NULL, 1),
(501504, 48380, 3306, '<td valign="top">Lighting is a little harsh on the flowers. Nice color.</td>', 'Lighting is a little harsh on the flowers. Nice color.', '2003-12-02 21:13:56.000000', NULL, 1),
