(501684, 48511, 6008, '<td valign="top">Nicely sharp pillar candle that has wonderful soft, warm tones. Composition is good, lighting is good, and the capture of the smoke is excellent as I''ve heard it is fairly difficult to capture/light smoke effectively.</td>', 'Nicely sharp pillar candle that has wonderful soft, warm tones. Composition is good, lighting is good, and the capture of the smoke is excellent as I''ve heard it is fairly difficult to capture/light smoke effectively.', '2003-12-02 23:43:26.000000', NULL, 1),
(501685, 47982, 12902, '<td valign="top">One of the best around. Running for the ribbon I am sure. very interesting effect created with lights. If I could not see the name anywhere, gold was the word that it would occured in my mind seeing this photo. !0 and congratulations.</td>', 'One of the best around. Running for the ribbon I am sure. very interesting effect created with lights. If I could not see the name anywhere, gold was the word that it would occured in my mind seeing this photo. !0 and congratulations.', '2003-12-02 23:44:47.000000', NULL, 1),
(501687, 48549, 6008, '<td valign="top">Center compositions are usually not very popular, but having the bowl at the intersection of the colorful mats make it far more interesting. The bowl is clear and sharp, and the popcorn is, well, clearly popcorn. Has a fairly abstract feel.</td>', 'Center compositions are usually not very popular, but having the bowl at the intersection of the colorful mats make it far more interesting. The bowl is clear and sharp, and the popcorn is, well, clearly popcorn. Has a fairly abstract feel.', '2003-12-02 23:46:39.000000', NULL, 1),
(501689, 48670, 12902, '<td valign="top">One of the best. I just wanted to give it at least the 10 that it deserves if I did not have the time during the week to comment on it. Not that it needed. I''m sure it has lots of comments anyway. 10 and congratulations!</td>', 'One of the best. I just wanted to give it at least the 10 that it deserves if I did not have the time during the week to comment on it. Not that it needed. I''m sure it has lots of comments anyway. 10 and congratulations!', '2003-12-02 23:46:58.000000', NULL, 1),
